# SPDX-License-Identifier: MIT
# Request-trace observer and trusted control for block/freeze ioctl fixtures
# (pane 214). Request numbers come from the guest's <linux/fs.h>: setup
# compiles ioctlnums.c with gcc and "ioctl_trace.py numbers" checks the
# output against the table below, so a wrong table is a setup ERROR.
# Usage:
#   ioctl_trace.py numbers OUTPUT-OF-IOCTLNUMS
#   ioctl_trace.py probe JSON-LIST [PATH]   (under the rules: [REQUEST-NAME, WANT] on a
#                                            scratch file, or on PATH opened read-only)
#   ioctl_trace.py control LOG JSON-LIST    (exact recorded ioctl names after probe)
#   ioctl_trace.py show LABEL LOG NAME...   (print opens of NAME... and ioctls)
import errno, fcntl, json, os, pathlib, sys

REQUESTS = {'BLKROSET': 0x125d, 'BLKROGET': 0x125e, 'BLKRRPART': 0x125f, 'BLKGETSIZE': 0x1260,
            'BLKFLSBUF': 0x1261, 'BLKSSZGET': 0x1268, 'BLKBSZGET': 0x80081270, 'BLKGETSIZE64': 0x80081272,
            'FIFREEZE': 0xc0045877, 'FITHAW': 0xc0045878}
BY_NUMBER = {v: k for k, v in REQUESTS.items()}
ZERO_ARG = {'BLKFLSBUF', 'BLKRRPART', 'FIFREEZE', 'FITHAW'}


def records(log):
    path = pathlib.Path(log)
    return [json.loads(line) for line in path.read_text().splitlines()] if path.exists() else []


def flags_text(value):
    mode = {os.O_RDONLY: 'RDONLY', os.O_WRONLY: 'WRONLY', os.O_RDWR: 'RDWR'}.get(value & 3, 'ACC3')
    # The kernel O_LARGEFILE bit (0o100000) is implied on 64-bit and not shown.
    rest = value & ~3 & ~0o100000
    words = [mode]
    for name in ('O_CLOEXEC', 'O_DIRECTORY', 'O_NONBLOCK', 'O_CREAT', 'O_TRUNC', 'O_NOCTTY', 'O_LARGEFILE'):
        bit = getattr(os, name, 0)
        if bit and rest & bit:
            words.append(name[2:])
            rest &= ~bit
    if rest:
        words.append('0x%x' % rest)
    return '|'.join(words)


def ioctl_names(items):
    out = []
    for r in items:
        if r['syscall'] != 'ioctl':
            continue
        name = BY_NUMBER.get(r.get('arg1'), '0x%x' % r.get('arg1', 0))
        if name in ZERO_ARG and 'arg2' in r:
            name += ':%d' % r['arg2']
        out.append(name)
    return out


def main():
    command = sys.argv[1]
    if command == 'numbers':
        got = dict(item.split('=') for item in pathlib.Path(sys.argv[2]).read_text().split())
        want = {k: '0x%x' % v for k, v in REQUESTS.items()}
        if got != want:
            print('CONTROL-FAILED request numbers from <linux/fs.h> %s, table %s' % (got, want))
            sys.exit(98)
        print('request numbers ok')
    elif command == 'probe':
        target = sys.argv[3] if len(sys.argv) > 3 else None
        if target is None:
            with open('ctl-scratch', 'wb') as handle:
                handle.write(b'\0' * 4096)
        fd = os.open(target or 'ctl-scratch', os.O_RDONLY | os.O_CLOEXEC)
        try:
            for name, want in json.loads(sys.argv[2]):
                try:
                    fcntl.ioctl(fd, REQUESTS[name], 0)
                    code = 0
                except OSError as error:
                    code = error.errno
                if code != (0 if want == 'ok' else getattr(errno, want)):
                    print('CONTROL-FAILED ioctl %s errno %d, wanted %s' % (name, code, want))
                    sys.exit(98)
        finally:
            os.close(fd)
            if target is None:
                os.unlink('ctl-scratch')
        print('mechanism control ok')
    elif command == 'control':
        log, want = sys.argv[2], json.loads(sys.argv[3])
        items = records(log)
        got = ioctl_names(items)
        opened = any(r['syscall'] == 'openat' and r.get('string1') == 'ctl-scratch' for r in items)
        has_openat = any(r['syscall'] == 'openat' for r in items)
        if got != want or (has_openat and not opened):
            print('CONTROL-FAILED notification log ioctls %s (wanted %s), scratch open recorded %s' % (got, want, opened))
            sys.exit(98)
        if os.path.exists(log):
            os.unlink(log)
        print('notification control ok')
    elif command == 'show':
        label, log, names = sys.argv[2], sys.argv[3], sys.argv[4:]
        items = records(log)
        opens = ['%s:%s' % (r['string1'], flags_text(r.get('arg2', 0))) for r in items
                 if r['syscall'] == 'openat' and r.get('string1') in names]
        with open('observations.txt', 'a') as handle:
            handle.write('[%s trace]\n%s\n' % (label, '\n'.join(json.dumps(r, sort_keys=True) for r in items)))
        if os.path.exists(log):
            os.unlink(log)
        print('%s opens=%s ioctls=%s' % (label, ','.join(opens) or '-', ','.join(ioctl_names(items)) or '-'))
    else:
        raise AssertionError(command)


if __name__ == '__main__':
    main()

