/* SPDX-License-Identifier: MIT */
/* Prints ioctl request numbers from the guest's <linux/fs.h> (pane 214). */
#include <stdio.h>
#include <linux/fs.h>

#define SHOW(name) printf ("%s=%#lx\n", #name, (unsigned long) (name))

int
main (void)
{
    SHOW (BLKROSET); SHOW (BLKROGET); SHOW (BLKRRPART); SHOW (BLKGETSIZE);
    SHOW (BLKFLSBUF); SHOW (BLKSSZGET); SHOW (BLKBSZGET); SHOW (BLKGETSIZE64);
    SHOW (FIFREEZE); SHOW (FITHAW);
    return 0;
}

